// Verify the HMAC-SHA256 signature the ingest Lambda puts on the webhook:
//   X-Signature: sha256=HMAC(WEBHOOK_SECRET, "<X-Timestamp>.<raw body>")
// and reject anything older than 5 minutes (replay protection).
const crypto = require('crypto');
const headers = $input.first().json.headers || {};
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const ts = headers['x-timestamp'];
const sig = String(headers['x-signature'] || '').replace(/^sha256=/, '');
const expected = crypto.createHmac('sha256', $env.WEBHOOK_SECRET || '').update(`${ts}.`).update(raw).digest('hex');

let valid = Boolean($env.WEBHOOK_SECRET) && Boolean(ts) && sig.length === expected.length
  && crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected))
  && Math.abs(Date.now() / 1000 - Number(ts)) <= 300;

let uploadJobId = null;
if (valid) {
  try { uploadJobId = JSON.parse(raw.toString('utf8')).upload_job_id; } catch (e) { valid = false; }
  valid = valid && /^[0-9a-f-]{36}$/.test(uploadJobId || '');
}
return [{ json: { valid, upload_job_id: uploadJobId } }];

// Stage 3: the LLM is used ONLY to turn free-text eligibility wording into structured thresholds,
// once per distinct wording (results cached in llm_cache). It is never called per user or per pair.
// ---- shared LLM helper (inlined into Code nodes by build_workflows.py) ----
// LLM_PROVIDER=gemini (hosted, rate-limited free tier) | ollama (local open model, unlimited, no key)
const LLM_PROVIDER = String($env.LLM_PROVIDER || 'gemini').toLowerCase();
function llmConfigError() {
  if (LLM_PROVIDER === 'gemini' && !$env.GEMINI_API_KEY) return 'LLM_PROVIDER=gemini but GEMINI_API_KEY is not set';
  if (LLM_PROVIDER !== 'gemini' && LLM_PROVIDER !== 'ollama') return `unknown LLM_PROVIDER "${LLM_PROVIDER}"`;
  return null;
}
// Returns the model's answer parsed as JSON. Retries transient failures with backoff.
async function callLLM(ctx, prompt) {
  let lastError;
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      let text;
      if (LLM_PROVIDER === 'ollama') {
        const resp = await ctx.helpers.httpRequest({
          method: 'POST', url: `${$env.OLLAMA_URL || 'http://ollama:11434'}/api/chat`, json: true, timeout: 300000,
          body: { model: $env.OLLAMA_MODEL || 'qwen2.5:3b', stream: false, format: 'json',
                  options: { temperature: 0 }, messages: [{ role: 'user', content: prompt }] },
        });
        text = resp.message.content;
      } else {
        const model = $env.GEMINI_MODEL || 'gemini-3.5-flash-lite';
        const resp = await ctx.helpers.httpRequest({
          method: 'POST', json: true, timeout: 90000,
          url: `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`,
          headers: { 'x-goog-api-key': $env.GEMINI_API_KEY, 'Content-Type': 'application/json' },
          body: { contents: [{ parts: [{ text: prompt }] }],
                  generationConfig: { responseMimeType: 'application/json', temperature: 0 } },
        });
        text = resp.candidates[0].content.parts.find((p) => typeof p.text === 'string').text;
      }
      return JSON.parse(text);
    } catch (e) {
      lastError = e;
      if (attempt < 3) await new Promise((r) => setTimeout(r, 2000 * attempt));
    }
  }
  throw lastError;
}
// ---- end shared helper ----

const EMPLOYMENT = ['Salaried', 'Self-Employed', 'Business'];

const todo = [];
const seen = new Set();
for (const item of $input.all()) {
  const r = item.json;
  if (!r.cache_key || seen.has(r.cache_key)) continue;
  seen.add(r.cache_key);
  todo.push(r);
}

const num = (v) => (typeof v === 'number' && isFinite(v) && v >= 0 ? v : null);
const rows = [];
const errors = [];
let calls = 0;

const configError = llmConfigError();
if (todo.length && configError) {
  errors.push(`${configError}: ${todo.length} product(s) with free-text criteria were skipped`);
} else {
  for (const r of todo) {
    const prompt =
      'Extract loan eligibility thresholds from the text below. Respond with a single JSON object using exactly these keys: ' +
      'min_income (minimum MONTHLY income as a number, convert yearly figures to monthly), min_credit_score, ' +
      'max_credit_score, min_age, max_age, allowed_employment (array containing any of "Salaried", ' +
      '"Self-Employed", "Business"; null if not restricted). Use null for anything not stated. ' +
      'Do not guess.\n\nTEXT:\n' + r.criteria_text;
    let parsed;
    try {
      calls++;
      parsed = await callLLM(this, prompt);
    } catch (e) {
      errors.push(`${r.product_name}: ${e.message}`);
      continue;
    }
    // Sanity-check before caching: a wrong extraction would silently mis-match thousands of users.
    const t = { min_income: num(parsed.min_income), min_credit_score: num(parsed.min_credit_score),
                max_credit_score: num(parsed.max_credit_score), min_age: num(parsed.min_age), max_age: num(parsed.max_age) };
    const implausible =
      (t.min_income != null && (t.min_income < 1000 || t.min_income > 10000000)) ||
      [t.min_credit_score, t.max_credit_score].some((v) => v != null && (v < 300 || v > 900)) ||
      [t.min_age, t.max_age].some((v) => v != null && (v < 18 || v > 100)) ||
      (t.min_credit_score != null && t.max_credit_score != null && t.min_credit_score > t.max_credit_score) ||
      (t.min_age != null && t.max_age != null && t.min_age > t.max_age);
    if (implausible) {
      errors.push(`${r.product_name}: implausible extraction ${JSON.stringify(t)} (not cached)`);
      continue;
    }
    const allowed = Array.isArray(parsed.allowed_employment)
      ? parsed.allowed_employment.filter((e) => EMPLOYMENT.includes(e)) : [];
    rows.push({
      cache_key: r.cache_key,
      result: {
        min_income: num(parsed.min_income), min_credit_score: num(parsed.min_credit_score),
        max_credit_score: num(parsed.max_credit_score), min_age: num(parsed.min_age),
        max_age: num(parsed.max_age), allowed_employment: allowed.length ? allowed : null,
      },
    });
  }
}
const uploadJobId = $('Verify Signature').first().json.upload_job_id;
return [{ json: { upload_job_id: uploadJobId, rows, llm_calls: calls, errors } }];

// Stage 0: work only on the users of THIS upload, in fixed-size batches.
// The scoring weights and TOP_K live here (in n8n) and are passed to the SQL stage as parameters.
const BATCH_SIZE = 1000;
// MATCH_TOP_K: 'all' (default) stores every eligible match; a number keeps only the best K products per user.
const topK = String($env.MATCH_TOP_K || 'all').toLowerCase();
const CONFIG = { w_income: 0.35, w_credit: 0.25, w_rate: 0.4,
                 top_k: topK === 'all' || Number(topK) <= 0 || !Number.isFinite(Number(topK)) ? 1000000 : Math.floor(Number(topK)) };
const { upload_job_id } = $('Verify Signature').first().json;
const start = $('Start Run').first().json;
if (!Number(start.job_found)) {
  throw new Error(`Upload job ${upload_job_id} is not in a COMPLETED state; nothing to match`);
}
const batches = Math.max(1, Math.ceil(Number(start.users_count) / BATCH_SIZE));
return Array.from({ length: batches }, (_, i) => ({
  json: { upload_job_id, offset: i * BATCH_SIZE, batch_size: BATCH_SIZE, ...CONFIG },
}));

// Stage 2 result: Postgres already applied the hard criteria, scored each pair with the weights from
// "Plan Batches" and kept the top-K products per user, so only those rows reach n8n.
// Here we just shape them for the bulk insert and report how many pairs survived stage 1.
const uploadJobId = $('Verify Signature').first().json.upload_job_id;
const rows = $input.all().map((i) => i.json).filter((r) => r.product_id != null); // drop the empty-batch placeholder
return [{
  json: {
    upload_job_id: uploadJobId,
    pairs_after_sql: rows.length ? Number(rows[0].eligible_total) : 0,
    rows: rows.map((r) => ({
      user_id: r.user_id,
      product_id: Number(r.product_id),
      score: Number(r.score),
      match_stage: r.via_llm ? 'rules_llm' : 'rules',
      reasons: { income_fit: +Number(r.income_fit).toFixed(2), credit_fit: +Number(r.credit_fit).toFixed(2),
                 rate_fit: +Number(r.rate_fit).toFixed(2) },
    })),
  },
}];
